import { FormEvent, useEffect, useMemo, useState } from 'react';
import { EmptyState } from '../components/EmptyState';
import { ErrorState } from '../components/ErrorState';
import { Header } from '../components/Header';
import { LoadingState } from '../components/LoadingState';
import { PageHeader } from '../components/PageHeader';
import { customerService } from '../services/customerService';
import { authService } from '../services/authService';
import { orderService } from '../services/orderService';
import { planningService, type GoalInput, type Planning, type PlanningCategory, type PlanningEntityType, type PlanningGoal, type PlanningLink, type PlanningOpportunity, type PlanningPriority, type PlanningStatus, type PlanningTask, type PlanningTaskStatus, type PlanningTemplate, type RelatedPlanningOptions } from '../services/planningService';
import { productService } from '../services/productService';
import { purchaseService } from '../services/purchaseService';
import { supplierService } from '../services/supplierService';

type Tab = 'overview' | 'plans' | 'tasks' | 'goals' | 'agenda' | 'opportunities' | 'templates';
type FormLink = { entity_type: PlanningEntityType; entity_id: string };
type PlanDraft = { title: string; description: string; category: PlanningCategory; expected_outcome: string; start_date: string; due_date: string; status: PlanningStatus; priority: PlanningPriority; observations: string; task_titles: string; links: FormLink[] };
type TaskDraft = { title: string; description: string; stage: string; priority: PlanningPriority; due_date: string; observations: string; status: PlanningTaskStatus; assignee_id: string };
type GoalDraft = { name: string; description: string; category: PlanningCategory; initial_value: string; target_value: string; current_value: string; unit: string; start_date: string; due_date: string; status: PlanningGoal['status']; planning_id: string };
type RelatedOptions = RelatedPlanningOptions & { assignees: Array<{ id: string; name: string }> };

const categories: Array<{ value: PlanningCategory; label: string }> = [
  { value: 'commercial', label: 'Comercial' }, { value: 'customers', label: 'Clientes' }, { value: 'suppliers', label: 'Fornecedores' },
  { value: 'purchases', label: 'Compras' }, { value: 'inventory', label: 'Estoque' }, { value: 'finance', label: 'Financeiro' },
  { value: 'operational', label: 'Operacional' }, { value: 'strategic', label: 'Estratégico' }, { value: 'other', label: 'Outros' },
];
const statuses: Array<{ value: PlanningStatus; label: string }> = [
  { value: 'draft', label: 'Rascunho' }, { value: 'not_started', label: 'Não iniciado' }, { value: 'in_progress', label: 'Em andamento' },
  { value: 'on_hold', label: 'Em espera' }, { value: 'completed', label: 'Concluído' }, { value: 'cancelled', label: 'Cancelado' },
];
const priorities: Array<{ value: PlanningPriority; label: string }> = [
  { value: 'low', label: 'Baixa' }, { value: 'medium', label: 'Média' }, { value: 'high', label: 'Alta' }, { value: 'urgent', label: 'Urgente' },
];
const blankPlan: PlanDraft = { title: '', description: '', category: 'operational', expected_outcome: '', start_date: '', due_date: '', status: 'not_started', priority: 'medium', observations: '', task_titles: '', links: [] };
const blankTask: TaskDraft = { title: '', description: '', stage: '', priority: 'medium', due_date: '', observations: '', status: 'pending', assignee_id: '' };
const blankGoal: GoalDraft = { name: '', description: '', category: 'strategic', initial_value: '', target_value: '', current_value: '0', unit: '', start_date: '', due_date: '', status: 'in_progress', planning_id: '' };
const categoryLabel = (category: string) => categories.find((item) => item.value === category)?.label ?? category;
const statusLabel = (status: string) => statuses.find((item) => item.value === status)?.label ?? status;
const priorityLabel = (priority: string) => priorities.find((item) => item.value === priority)?.label ?? priority;
const dateLabel = (date?: string | null) => date ? new Intl.DateTimeFormat('pt-BR').format(new Date(`${date.slice(0, 10)}T12:00:00`)) : 'Sem prazo';
const todayKey = () => { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`; };
const isOverdue = (date?: string | null) => Boolean(date && date.slice(0, 10) < todayKey());

export function PlanningPage() {
  const [plans, setPlans] = useState<Planning[]>([]);
  const [goals, setGoals] = useState<PlanningGoal[]>([]);
  const [templates, setTemplates] = useState<PlanningTemplate[]>([]);
  const [opportunities, setOpportunities] = useState<PlanningOpportunity[]>([]);
  const [related, setRelated] = useState<RelatedOptions>({ customers: [], suppliers: [], products: [], purchases: [], orders: [], payables: [], receivables: [], assignees: [] });
  const [tab, setTab] = useState<Tab>('overview');
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');
  const [feedback, setFeedback] = useState('');
  const [planFormOpen, setPlanFormOpen] = useState(false);
  const [taskFormOpen, setTaskFormOpen] = useState(false);
  const [goalFormOpen, setGoalFormOpen] = useState(false);
  const [editingPlan, setEditingPlan] = useState<Planning | null>(null);
  const [editingTask, setEditingTask] = useState<PlanningTask | null>(null);
  const [editingGoal, setEditingGoal] = useState<PlanningGoal | null>(null);
  const [detailPlanId, setDetailPlanId] = useState('');
  const [planDraft, setPlanDraft] = useState<PlanDraft>(blankPlan);
  const [taskDraft, setTaskDraft] = useState<TaskDraft>(blankTask);
  const [goalDraft, setGoalDraft] = useState<GoalDraft>(blankGoal);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [dueFrom, setDueFrom] = useState('');
  const [dueTo, setDueTo] = useState('');
  const [includeArchived, setIncludeArchived] = useState(false);
  const [view, setView] = useState<'list' | 'board'>('list');
  const [agendaRange, setAgendaRange] = useState<'day' | 'week' | 'month'>('week');

  const refresh = async () => {
    const [nextPlans, nextGoals, nextTemplates, nextOpportunities] = await Promise.all([
      planningService.list({ include_archived: includeArchived }), planningService.goals(), planningService.templates(), planningService.opportunities(),
    ]);
    setPlans(nextPlans); setGoals(nextGoals); setTemplates(nextTemplates); setOpportunities(nextOpportunities);
    setDetailPlanId((current) => nextPlans.some((plan) => plan.id === current) ? current : '');
  };
  useEffect(() => {
    let active = true;
    setIsLoading(true); setError('');
    void Promise.all([planningService.list({ include_archived: includeArchived }), planningService.goals(), planningService.templates(), planningService.opportunities()])
      .then(([nextPlans, nextGoals, nextTemplates, nextOpportunities]) => { if (active) { setPlans(nextPlans); setGoals(nextGoals); setTemplates(nextTemplates); setOpportunities(nextOpportunities); } })
      .catch((reason: unknown) => { if (active) setError(reason instanceof Error ? reason.message : 'Não foi possível carregar os dados de planejamento.'); })
      .finally(() => { if (active) setIsLoading(false); });
    void Promise.allSettled([customerService.getAll(), supplierService.getActiveOptions(), productService.getAll(), purchaseService.getAll(), orderService.getAll(), planningService.financialLinkOptions(), authService.getUsers()])
      .then((results) => { if (!active) return; setRelated({
        customers: results[0].status === 'fulfilled' ? results[0].value.map((item) => ({ id: item.id, name: item.company || item.name })) : [],
        suppliers: results[1].status === 'fulfilled' ? results[1].value : [],
        products: results[2].status === 'fulfilled' ? results[2].value.map((item) => ({ id: item.id, name: item.name })) : [],
        purchases: results[3].status === 'fulfilled' ? results[3].value.map((item) => ({ id: item.id, name: `${item.supplier} · ${dateLabel(item.date)} · ${item.totalValue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}` })) : [],
        orders: results[4].status === 'fulfilled' ? results[4].value.map((item) => ({ id: item.id, name: `${item.customer} · ${dateLabel(item.date)} · ${item.value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}` })) : [],
        payables: results[5].status === 'fulfilled' ? results[5].value.payables : [],
        receivables: results[5].status === 'fulfilled' ? results[5].value.receivables : [],
        assignees: results[6].status === 'fulfilled' ? results[6].value.map((item) => ({ id: item.id, name: item.name })) : [],
      }); });
    return () => { active = false; };
  }, [includeArchived]);

  const activePlans = plans.filter((plan) => !plan.archived);
  const allTasks = plans.flatMap((plan) => plan.tasks.map((task) => ({ ...task, planning_title: plan.title })));
  const pendingTasks = allTasks.filter((task) => task.status !== 'completed');
  const overdueTasks = pendingTasks.filter((task) => isOverdue(task.due_date));
  const upcomingPlans = activePlans.filter((plan) => plan.due_date && !isOverdue(plan.due_date) && plan.status !== 'completed' && plan.status !== 'cancelled').sort((a, b) => (a.due_date ?? '').localeCompare(b.due_date ?? '')).slice(0, 5);
  const activeGoals = goals.filter((goal) => goal.status === 'in_progress');
  const filteredPlans = useMemo(() => plans.filter((plan) => {
    return (includeArchived || !plan.archived)
      && (statusFilter === 'all' || plan.status === statusFilter)
      && (categoryFilter === 'all' || plan.category === categoryFilter)
      && (priorityFilter === 'all' || plan.priority === priorityFilter)
      && (!dueFrom || Boolean(plan.due_date && plan.due_date >= dueFrom))
      && (!dueTo || Boolean(plan.due_date && plan.due_date <= dueTo))
      && (!search || plan.title.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR')));
  }), [plans, includeArchived, statusFilter, categoryFilter, priorityFilter, dueFrom, dueTo, search]);
  const detailPlan = plans.find((plan) => plan.id === detailPlanId) ?? null;

  const openNewPlan = (template?: PlanningTemplate, opportunity?: PlanningOpportunity) => {
    setEditingPlan(null);
    setPlanDraft({ ...blankPlan, ...(template ? { title: template.title, description: template.description, category: template.category, task_titles: template.tasks.join('\n') } : {}), ...(opportunity ? { title: opportunity.title, description: opportunity.reason, category: opportunity.category, task_titles: 'Conferir estoque físico\nAvaliar a necessidade de reposição\nConsultar condições do fornecedor', links: [{ entity_type: opportunity.entity_type, entity_id: opportunity.entity_id }] } : {}) });
    setTab('plans'); setPlanFormOpen(true); setFeedback('');
  };
  const openEditPlan = (plan: Planning) => {
    setEditingPlan(plan);
    setPlanDraft({ title: plan.title, description: plan.description ?? '', category: plan.category, expected_outcome: plan.expected_outcome ?? '', start_date: plan.start_date ?? '', due_date: plan.due_date ?? '', status: plan.status, priority: plan.priority, observations: plan.observations ?? '', task_titles: '', links: plan.links.map(({ entity_type, entity_id }) => ({ entity_type, entity_id })) });
    setPlanFormOpen(true); setFeedback('');
  };
  const savePlan = async (event: FormEvent) => {
    event.preventDefault(); setIsSaving(true); setError(''); setFeedback('');
    try {
      const input = { title: planDraft.title.trim(), description: planDraft.description.trim() || null, category: planDraft.category, expected_outcome: planDraft.expected_outcome.trim() || null, start_date: planDraft.start_date || null, due_date: planDraft.due_date || null, status: planDraft.status, priority: planDraft.priority, observations: planDraft.observations.trim() || null, links: planDraft.links, ...(!editingPlan ? { tasks: planDraft.task_titles.split('\n').map((title) => title.trim()).filter(Boolean).map((title, index) => ({ title, sort_order: index })) } : {}) };
      if (editingPlan) await planningService.update(editingPlan.id, input); else await planningService.create(input);
      setPlanFormOpen(false); setFeedback(editingPlan ? 'Planejamento atualizado.' : 'Planejamento criado.'); await refresh();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível salvar o planejamento.'); }
    finally { setIsSaving(false); }
  };
  const setPlanStatus = async (plan: Planning, status: PlanningStatus) => {
    try { setError(''); await planningService.update(plan.id, { status }); setFeedback(`Planejamento ${statusLabel(status).toLocaleLowerCase('pt-BR')}.`); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível atualizar o planejamento.'); }
  };
  const archivePlan = async (plan: Planning) => {
    if (!window.confirm(`Arquivar o planejamento “${plan.title}”?`)) return;
    try { setError(''); await planningService.update(plan.id, { archived: !plan.archived }); setFeedback(plan.archived ? 'Planejamento reativado.' : 'Planejamento arquivado.'); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível arquivar o planejamento.'); }
  };
  const openNewTask = (plan: Planning) => { setEditingTask(null); setTaskDraft(blankTask); setDetailPlanId(plan.id); setTaskFormOpen(true); };
  const openEditTask = (task: PlanningTask) => { setEditingTask(task); setTaskDraft({ title: task.title, description: task.description ?? '', stage: task.stage ?? '', priority: task.priority, due_date: task.due_date ?? '', observations: task.observations ?? '', status: task.status, assignee_id: task.assignee_id ?? '' }); setTaskFormOpen(true); };
  const saveTask = async (event: FormEvent) => {
    event.preventDefault(); if (!detailPlan) return; setIsSaving(true); setError('');
    try {
      const input = { title: taskDraft.title.trim(), description: taskDraft.description.trim() || null, stage: taskDraft.stage.trim() || null, priority: taskDraft.priority, due_date: taskDraft.due_date || null, observations: taskDraft.observations.trim() || null, status: taskDraft.status, assignee_id: taskDraft.assignee_id || null };
      if (editingTask) await planningService.updateTask(editingTask.id, input); else await planningService.createTask(detailPlan.id, input);
      setTaskFormOpen(false); setFeedback(editingTask ? 'Tarefa atualizada.' : 'Tarefa adicionada.'); await refresh();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível salvar a tarefa.'); }
    finally { setIsSaving(false); }
  };
  const toggleTask = async (task: PlanningTask) => {
    try { await planningService.updateTask(task.id, { status: task.status === 'completed' ? 'pending' : 'completed' }); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível atualizar a tarefa.'); }
  };
  const deleteTask = async (task: PlanningTask) => {
    if (!window.confirm(`Excluir a tarefa “${task.title}”?`)) return;
    try { await planningService.deleteTask(task.id); setFeedback('Tarefa excluída.'); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível excluir a tarefa.'); }
  };
  const openNewGoal = (planId = '') => { setEditingGoal(null); setGoalDraft({ ...blankGoal, planning_id: planId }); setGoalFormOpen(true); };
  const openEditGoal = (goal: PlanningGoal) => { setEditingGoal(goal); setGoalDraft({ name: goal.name, description: goal.description ?? '', category: goal.category, initial_value: goal.initial_value == null ? '' : String(goal.initial_value), target_value: String(goal.target_value), current_value: String(goal.current_value), unit: goal.unit, start_date: goal.start_date ?? '', due_date: goal.due_date ?? '', status: goal.status, planning_id: goal.planning_id ?? '' }); setGoalFormOpen(true); };
  const saveGoal = async (event: FormEvent) => {
    event.preventDefault(); setIsSaving(true); setError('');
    try {
      const input: GoalInput = { name: goalDraft.name.trim(), description: goalDraft.description.trim() || null, category: goalDraft.category, initial_value: goalDraft.initial_value === '' ? null : Number(goalDraft.initial_value), target_value: Number(goalDraft.target_value), current_value: Number(goalDraft.current_value), unit: goalDraft.unit.trim(), start_date: goalDraft.start_date || null, due_date: goalDraft.due_date || null, status: goalDraft.status, planning_id: goalDraft.planning_id || null };
      if (editingGoal) await planningService.updateGoal(editingGoal.id, input); else await planningService.createGoal(input);
      setGoalFormOpen(false); setFeedback(editingGoal ? 'Meta atualizada.' : 'Meta criada.'); await refresh();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível salvar a meta.'); }
    finally { setIsSaving(false); }
  };
  const updateGoalValue = async (goal: PlanningGoal) => {
    const value = window.prompt(`Informe o valor atual de “${goal.name}” (${goal.unit}):`, String(goal.current_value));
    if (value === null) return;
    const currentValue = Number(value.replace(',', '.'));
    if (!Number.isFinite(currentValue) || currentValue < 0) { setError('Informe um valor atual válido, igual ou maior que zero.'); return; }
    try { await planningService.updateGoal(goal.id, { current_value: currentValue, status: currentValue >= goal.target_value && goal.target_value > 0 ? 'completed' : 'in_progress' }); setFeedback('Progresso da meta atualizado.'); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível atualizar a meta.'); }
  };
  const dismissOpportunity = async (opportunity: PlanningOpportunity) => {
    if (opportunity.entity_type !== 'product') return;
    try { await planningService.dismissOpportunity(opportunity.entity_id); setFeedback('Sugestão dispensada.'); await refresh(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Não foi possível dispensar a sugestão.'); }
  };
  const setLink = (entity_type: PlanningEntityType, entity_id: string) => setPlanDraft((draft) => ({ ...draft, links: entity_id ? [...draft.links.filter((item) => item.entity_type !== entity_type), { entity_type, entity_id }] : draft.links.filter((item) => item.entity_type !== entity_type) }));
  const taskRows = useMemo(() => [...allTasks].sort((a, b) => (a.due_date ?? '9999').localeCompare(b.due_date ?? '9999')), [plans]);
  const agendaItems = useMemo(() => {
    const today = new Date(`${todayKey()}T00:00:00`);
    const end = new Date(today);
    if (agendaRange === 'day') end.setDate(end.getDate() + 1);
    if (agendaRange === 'week') end.setDate(end.getDate() + 7);
    if (agendaRange === 'month') end.setMonth(end.getMonth() + 1);
    const items: Array<{ date: string; title: string; detail: string; kind: string; href: () => void; overdue?: boolean }> = [];
    activePlans.forEach((plan) => {
      if (plan.start_date && plan.start_date >= todayKey() && new Date(`${plan.start_date}T12:00:00`) <= end) items.push({ date: plan.start_date, title: plan.title, detail: 'Início do planejamento', kind: 'Planejamento', href: () => setDetailPlanId(plan.id) });
      if (plan.due_date && plan.status !== 'completed' && new Date(`${plan.due_date}T12:00:00`) <= end) items.push({ date: plan.due_date, title: plan.title, detail: 'Prazo final do planejamento', kind: 'Planejamento', href: () => setDetailPlanId(plan.id), overdue: isOverdue(plan.due_date) });
    });
    allTasks.forEach((task) => { if (task.due_date && task.status !== 'completed' && new Date(`${task.due_date}T12:00:00`) <= end) items.push({ date: task.due_date, title: task.title, detail: task.planning_title, kind: 'Tarefa', href: () => setDetailPlanId(task.planning_id), overdue: isOverdue(task.due_date) }); });
    goals.forEach((goal) => { if (goal.due_date && goal.status === 'in_progress' && new Date(`${goal.due_date}T12:00:00`) <= end) items.push({ date: goal.due_date, title: goal.name, detail: `Meta · ${goal.current_value} de ${goal.target_value} ${goal.unit}`, kind: 'Meta', href: () => setTab('goals'), overdue: isOverdue(goal.due_date) }); });
    return items.sort((a, b) => a.date.localeCompare(b.date));
  }, [plans, goals, agendaRange]);

  const tabs: Array<{ id: Tab; label: string }> = [{ id: 'overview', label: 'Visão geral' }, { id: 'plans', label: 'Planejamentos' }, { id: 'tasks', label: 'Tarefas' }, { id: 'goals', label: 'Metas' }, { id: 'agenda', label: 'Agenda' }, { id: 'opportunities', label: 'Oportunidades' }, { id: 'templates', label: 'Modelos' }];
  const createButton = <button className="btn btn--primary" type="button" onClick={() => openNewPlan()}>+ Novo planejamento</button>;
  const renderTaskTable = (tasks: Array<PlanningTask & { planning_title?: string }>, showPlan: boolean) => tasks.length ? <div className="table-scroll"><table className="table"><thead><tr><th>Tarefa</th>{showPlan ? <th>Planejamento</th> : null}<th>Etapa</th><th>Responsável</th><th>Prioridade</th><th>Prazo</th><th>Status</th><th>Ações</th></tr></thead><tbody>{tasks.map((task) => <tr key={task.id}><td><strong className={task.status === 'completed' ? 'planning-completed-text' : ''}>{task.title}</strong><small>{task.description || task.observations || 'Sem observações'}</small></td>{showPlan ? <td><button className="planning-text-button" type="button" onClick={() => setDetailPlanId(task.planning_id)}>{task.planning_title}</button></td> : null}<td>{task.stage || '—'}</td><td>{task.assignee_name || '—'}</td><td><span className={`planning-priority planning-priority--${task.priority}`}>{priorityLabel(task.priority)}</span></td><td className={isOverdue(task.due_date) && task.status !== 'completed' ? 'planning-overdue' : ''}>{dateLabel(task.due_date)}</td><td>{task.status === 'completed' ? 'Concluída' : task.status === 'in_progress' ? 'Em andamento' : 'Pendente'}</td><td><div className="table-actions"><button type="button" onClick={() => void toggleTask(task)}>{task.status === 'completed' ? 'Reabrir' : 'Concluir'}</button><button type="button" onClick={() => openEditTask(task)}>Editar</button><button className="table-action-danger" type="button" onClick={() => void deleteTask(task)}>Excluir</button></div></td></tr>)}</tbody></table></div> : <EmptyState title="Nenhuma tarefa" description="Adicione tarefas a um planejamento para acompanhar etapas e prazos." />;

  if (isLoading) return <div className="page-shell"><LoadingState message="Carregando planejamentos…" /></div>;
  if (error && !plans.length && !goals.length) return <div className="page-shell"><Header title="Planejar" breadcrumb="Administração / Planejar" /><ErrorState message={error} /><button className="btn btn--secondary" type="button" onClick={() => { setIsLoading(true); void refresh().catch((reason) => setError(reason instanceof Error ? reason.message : 'Falha ao carregar.')).finally(() => setIsLoading(false)); }}>Tentar novamente</button></div>;

  return <><Header title="Planejar" breadcrumb="Administração / Planejar" /><div className="page-shell planning-page">
    <PageHeader title="Planejar" description="Organize prioridades, tarefas, metas e prazos a partir dos registros da empresa." actions={createButton} />
    {error ? <ErrorState message={error} /> : null}{feedback ? <div className="inline-feedback" role="status">{feedback}</div> : null}
    <nav className="planning-tabs" aria-label="Áreas de planejamento">{tabs.map((item) => <button key={item.id} type="button" className={tab === item.id ? 'planning-tab planning-tab--active' : 'planning-tab'} onClick={() => setTab(item.id)}>{item.label}</button>)}</nav>

    {tab === 'overview' ? <>
      <section className="planning-metrics" aria-label="Indicadores de planejamento"><article><span>PLANEJAMENTOS</span><strong>{activePlans.length}</strong></article><article><span>EM ANDAMENTO</span><strong>{activePlans.filter((plan) => plan.status === 'in_progress').length}</strong></article><article><span>CONCLUÍDOS</span><strong>{activePlans.filter((plan) => plan.status === 'completed').length}</strong></article><article><span>TAREFAS PENDENTES</span><strong>{pendingTasks.length}</strong></article><article className={overdueTasks.length ? 'planning-metric--warning' : ''}><span>TAREFAS ATRASADAS</span><strong>{overdueTasks.length}</strong></article><article><span>METAS EM ANDAMENTO</span><strong>{activeGoals.length}</strong></article></section>
      {!plans.length && !goals.length ? <EmptyState title="Comece pelo primeiro planejamento" description="Crie um plano em branco ou use um modelo para organizar atividades, prazos e metas. Nenhum registro será criado até você salvar." action={createButton} /> : <div className="planning-overview-grid"><section className="panel"><div className="panel__header"><div><h3>Atividades prioritárias</h3><p className="panel__description">Tarefas urgentes, atrasadas e com prazo próximo.</p></div><button type="button" className="planning-text-button" onClick={() => setTab('tasks')}>Ver tarefas</button></div>{pendingTasks.length ? <div className="planning-priority-list">{[...pendingTasks].sort((a, b) => Number(isOverdue(b.due_date)) - Number(isOverdue(a.due_date)) || priorities.findIndex((item) => item.value === b.priority) - priorities.findIndex((item) => item.value === a.priority)).slice(0, 6).map((task) => <button type="button" className="planning-priority-row" key={task.id} onClick={() => setDetailPlanId(task.planning_id)}><span className={`planning-priority planning-priority--${task.priority}`}>{isOverdue(task.due_date) ? 'Atrasada' : priorityLabel(task.priority)}</span><span><strong>{task.title}</strong><small>{task.planning_title} · {dateLabel(task.due_date)}</small></span><span aria-hidden="true">›</span></button>)}</div> : <p className="table-state">Nenhuma tarefa pendente.</p>}</section><section className="panel"><div className="panel__header"><div><h3>Próximos prazos</h3><p className="panel__description">Planejamentos ativos com prazo final mais próximo.</p></div></div>{upcomingPlans.length ? <ul className="planning-deadline-list">{upcomingPlans.map((plan) => <li key={plan.id}><button type="button" onClick={() => setDetailPlanId(plan.id)}><strong>{plan.title}</strong><small>{dateLabel(plan.due_date)} · {plan.progress_percent}% concluído</small></button></li>)}</ul> : <p className="table-state">Não há prazos futuros registrados.</p>}</section></div>}
    </> : null}

    {tab === 'plans' ? <section className="panel"><div className="panel__header"><div><h2>Meus planejamentos</h2><p className="panel__description">O progresso é a proporção de tarefas concluídas; sem tarefas, permanece em 0%.</p></div><div className="planning-inline-actions"><button className="btn btn--secondary" type="button" onClick={() => setView('list')} aria-pressed={view === 'list'}>Lista</button><button className="btn btn--secondary" type="button" onClick={() => setView('board')} aria-pressed={view === 'board'}>Quadro</button></div></div>
      <div className="planning-filters"><input aria-label="Buscar por título" placeholder="Buscar planejamento" value={search} onChange={(event) => setSearch(event.target.value)} /><select aria-label="Filtrar status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="all">Todos os status</option>{statuses.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select><select aria-label="Filtrar categoria" value={categoryFilter} onChange={(event) => setCategoryFilter(event.target.value)}><option value="all">Todas as categorias</option>{categories.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select><select aria-label="Filtrar prioridade" value={priorityFilter} onChange={(event) => setPriorityFilter(event.target.value)}><option value="all">Todas as prioridades</option>{priorities.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select><label>Prazo a partir de<input aria-label="Prazo a partir de" type="date" value={dueFrom} onChange={(event) => setDueFrom(event.target.value)} /></label><label>Prazo até<input aria-label="Prazo até" type="date" value={dueTo} onChange={(event) => setDueTo(event.target.value)} /></label><label className="planning-archived-filter"><input type="checkbox" checked={includeArchived} onChange={(event) => setIncludeArchived(event.target.checked)} /> Incluir arquivados</label></div>
      {!filteredPlans.length ? <EmptyState title="Nenhum planejamento encontrado" description="Ajuste os filtros ou crie um planejamento para começar." action={createButton} /> : view === 'list' ? <div className="planning-card-list">{filteredPlans.map((plan) => <article className="planning-card" key={plan.id}><div className="planning-card__main"><div className="planning-card__title"><div><span>{categoryLabel(plan.category)} · {priorityLabel(plan.priority)}</span><h3>{plan.title}</h3></div><span className={`planning-status-badge planning-status-badge--${plan.status}`}>{statusLabel(plan.status)}</span></div>{plan.description ? <p>{plan.description}</p> : null}<div className="planning-progress"><div><span>Progresso</span><strong>{plan.progress_percent}%</strong></div><progress value={plan.progress_percent} max={100} /></div><small className="planning-card__meta">{plan.completed_task_count}/{plan.task_count} tarefas · Prazo {dateLabel(plan.due_date)}{plan.archived ? ' · Arquivado' : ''}</small>{plan.links.length ? <div className="planning-link-chips">{plan.links.map((link) => <span key={link.id}>{link.entity_type}: {link.label}</span>)}</div> : null}</div><div className="planning-card__actions"><button className="btn btn--secondary" type="button" onClick={() => setDetailPlanId(plan.id)}>Abrir</button><button className="btn btn--secondary" type="button" onClick={() => openEditPlan(plan)}>Editar</button>{plan.status !== 'completed' && plan.status !== 'cancelled' ? <button className="btn btn--primary" type="button" onClick={() => void setPlanStatus(plan, 'completed')}>Concluir</button> : null}<button className="btn btn--secondary" type="button" onClick={() => void archivePlan(plan)}>{plan.archived ? 'Reativar' : 'Arquivar'}</button></div></article>)}</div> : <div className="planning-board">{statuses.map(({ value: boardStatus }) => <section className="planning-board__column" key={boardStatus}><h3>{statusLabel(boardStatus)} <span>{filteredPlans.filter((plan) => plan.status === boardStatus).length}</span></h3>{filteredPlans.filter((plan) => plan.status === boardStatus).map((plan) => <button key={plan.id} type="button" className="planning-board-card" onClick={() => setDetailPlanId(plan.id)}><strong>{plan.title}</strong><small>{categoryLabel(plan.category)} · {dateLabel(plan.due_date)}</small><progress value={plan.progress_percent} max={100} /><small>{plan.progress_percent}%</small></button>)}</section>)}</div>}
    </section> : null}

    {tab === 'tasks' ? <section className="panel"><div className="panel__header"><div><h2>Tarefas e etapas</h2><p className="panel__description">As tarefas concluídas são registradas com data; reabrir remove a data de conclusão.</p></div></div>{renderTaskTable(taskRows, true)}</section> : null}

    {tab === 'goals' ? <section className="panel"><div className="panel__header"><div><h2>Metas e resultados</h2><p className="panel__description">Valores atuais são informados manualmente e não representam resultados automáticos da operação.</p></div><button className="btn btn--primary" type="button" onClick={() => openNewGoal()}>+ Nova meta</button></div>{goals.length ? <div className="planning-goal-grid">{goals.map((goal) => <article className="planning-goal-card" key={goal.id}><div className="planning-card__title"><div><span>{categoryLabel(goal.category)} · {goal.status === 'in_progress' ? 'Em andamento' : goal.status === 'completed' ? 'Concluída' : 'Cancelada'}</span><h3>{goal.name}</h3></div><strong>{goal.progress_percent.toFixed(0)}%</strong></div>{goal.description ? <p>{goal.description}</p> : null}<div className="planning-goal-values"><strong>{goal.current_value.toLocaleString('pt-BR')} {goal.unit}</strong><span>Meta: {goal.target_value.toLocaleString('pt-BR')} {goal.unit}</span></div><progress value={goal.progress_percent} max={100} /><small>Prazo: {dateLabel(goal.due_date)}{goal.planning_id ? ` · ${plans.find((plan) => plan.id === goal.planning_id)?.title ?? 'Planejamento vinculado'}` : ''}</small><div className="planning-inline-actions"><button type="button" className="btn btn--secondary" onClick={() => void updateGoalValue(goal)}>Atualizar valor</button><button type="button" className="btn btn--secondary" onClick={() => openEditGoal(goal)}>Editar meta</button></div></article>)}</div> : <EmptyState title="Nenhuma meta cadastrada" description="Registre um objetivo mensurável e atualize seu resultado conforme os dados forem apurados." action={<button className="btn btn--primary" type="button" onClick={() => openNewGoal()}>Criar primeira meta</button>} />}</section> : null}

    {tab === 'agenda' ? <section className="panel"><div className="panel__header"><div><h2>Agenda de prazos</h2><p className="panel__description">Linha do tempo criada a partir dos prazos de planejamentos, tarefas e metas.</p></div><div className="planning-inline-actions">{(['day', 'week', 'month'] as const).map((range) => <button key={range} type="button" className="btn btn--secondary" aria-pressed={agendaRange === range} onClick={() => setAgendaRange(range)}>{range === 'day' ? 'Dia' : range === 'week' ? 'Semana' : 'Mês'}</button>)}</div></div>{overdueTasks.length ? <div className="planning-agenda-overdue"><strong>{overdueTasks.length} tarefa(s) atrasada(s)</strong><button type="button" onClick={() => setTab('tasks')}>Ver tarefas atrasadas</button></div> : null}{agendaItems.length ? <div className="planning-timeline">{agendaItems.map((item, index) => <button type="button" className={`planning-timeline__item${item.overdue ? ' planning-timeline__item--overdue' : ''}`} key={`${item.kind}-${item.title}-${item.date}-${index}`} onClick={item.href}><time>{dateLabel(item.date)}</time><span><strong>{item.title}</strong><small>{item.kind} · {item.detail}</small></span>{item.overdue ? <b>Atrasado</b> : null}</button>)}</div> : <EmptyState title="Nenhum prazo neste período" description="Datas aparecem aqui quando forem adicionadas a planejamentos, tarefas ou metas." />}</section> : null}

    {tab === 'opportunities' ? <section className="panel"><div className="panel__header"><div><h2>Oportunidades</h2><p className="panel__description">Regra ativa: produtos com saldo registrado abaixo do estoque mínimo. Confirme o estoque físico antes de agir.</p></div><button className="btn btn--secondary" type="button" onClick={() => void refresh().catch((reason) => setError(reason instanceof Error ? reason.message : 'Falha ao atualizar.'))}>Atualizar</button></div>{opportunities.length ? <div className="planning-opportunity-list">{opportunities.map((item) => <article key={item.id}><span className="planning-opportunity-list__tag">{categoryLabel(item.category)}</span><div><h3>{item.title}</h3><p>{item.reason}</p><small>Identificada em {new Intl.DateTimeFormat('pt-BR').format(new Date(item.identified_at))} · Produto: {item.entity_label}</small></div><div className="planning-inline-actions"><button className="btn btn--primary" type="button" onClick={() => openNewPlan(undefined, item)}>Criar planejamento</button><button className="btn btn--secondary" type="button" onClick={() => void dismissOpportunity(item)}>Dispensar</button></div></article>)}</div> : <EmptyState title="Nenhuma oportunidade identificada" description="Não há produtos abaixo do estoque mínimo cadastrado. A análise usa somente os saldos e limites retornados pela API." />}</section> : null}

    {tab === 'templates' ? <section className="panel"><div className="panel__header"><div><h2>Modelos de planejamento</h2><p className="panel__description">Modelos padrão; usar um deles cria um planejamento independente, sem alterar o modelo.</p></div></div><div className="planning-template-grid">{templates.map((template) => <article key={template.key}><span>{categoryLabel(template.category)}</span><h3>{template.title}</h3><p>{template.description}</p><small>{template.tasks.length} tarefas sugeridas</small><button className="btn btn--primary" type="button" onClick={() => openNewPlan(template)}>Usar modelo</button></article>)}</div></section> : null}

    {detailPlan ? <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setDetailPlanId(''); }}><section className="admin-modal planning-detail-modal" role="dialog" aria-modal="true" aria-labelledby="planning-detail-title"><header className="admin-modal__header"><div><span className="eyebrow">{categoryLabel(detailPlan.category)} · {statusLabel(detailPlan.status)}</span><h2 id="planning-detail-title">{detailPlan.title}</h2></div><button type="button" aria-label="Fechar" onClick={() => setDetailPlanId('')}>×</button></header>{detailPlan.description ? <p>{detailPlan.description}</p> : null}<div className="planning-detail-facts"><span>Prioridade<strong>{priorityLabel(detailPlan.priority)}</strong></span><span>Início<strong>{dateLabel(detailPlan.start_date)}</strong></span><span>Prazo<strong>{dateLabel(detailPlan.due_date)}</strong></span><span>Progresso<strong>{detailPlan.progress_percent}% ({detailPlan.completed_task_count}/{detailPlan.task_count})</strong></span></div>{detailPlan.expected_outcome ? <p><strong>Resultado esperado:</strong> {detailPlan.expected_outcome}</p> : null}{detailPlan.links.length ? <div className="planning-link-chips">{detailPlan.links.map((link) => <span key={link.id}>{link.entity_type}: {link.label}</span>)}</div> : null}<div className="panel__header"><div><h3>Tarefas</h3></div><button type="button" className="btn btn--secondary" onClick={() => openNewTask(detailPlan)}>+ Adicionar tarefa</button></div>{detailPlan.tasks.length ? <div className="planning-detail-tasks">{detailPlan.tasks.map((task) => <div key={task.id}><button type="button" className={task.status === 'completed' ? 'planning-task-check planning-task-check--done' : 'planning-task-check'} aria-label={task.status === 'completed' ? 'Reabrir tarefa' : 'Concluir tarefa'} onClick={() => void toggleTask(task)}>{task.status === 'completed' ? '✓' : ''}</button><span><strong className={task.status === 'completed' ? 'planning-completed-text' : ''}>{task.title}</strong><small>{task.stage || 'Sem etapa'} · {dateLabel(task.due_date)}{task.status === 'completed' ? ` · Concluída em ${dateLabel(task.completed_at)}` : ''}</small></span><button className="planning-text-button" type="button" onClick={() => openEditTask(task)}>Editar</button><button className="planning-text-button planning-danger-text" type="button" onClick={() => void deleteTask(task)}>Excluir</button></div>)}</div> : <p className="table-state">Este planejamento não tem tarefas; seu progresso continua em 0%.</p>}<div className="admin-modal__actions"><button type="button" className="btn btn--secondary" onClick={() => openEditPlan(detailPlan)}>Editar planejamento</button>{detailPlan.status !== 'completed' ? <button type="button" className="btn btn--primary" onClick={() => void setPlanStatus(detailPlan, 'completed')}>Concluir planejamento</button> : null}<button type="button" className="btn btn--secondary" onClick={() => openNewGoal(detailPlan.id)}>Adicionar meta</button></div></section></div> : null}

    {planFormOpen ? <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !isSaving) setPlanFormOpen(false); }}><form className="admin-modal planning-form-modal" role="dialog" aria-modal="true" aria-labelledby="plan-form-title" onSubmit={(event) => void savePlan(event)}><header className="admin-modal__header"><div><span className="eyebrow">PLANEJAMENTO</span><h2 id="plan-form-title">{editingPlan ? 'Editar planejamento' : 'Novo planejamento'}</h2></div><button type="button" aria-label="Fechar" onClick={() => setPlanFormOpen(false)}>×</button></header><div className="planning-form-grid"><label>Título<input required minLength={2} maxLength={180} value={planDraft.title} onChange={(event) => setPlanDraft((current) => ({ ...current, title: event.target.value }))} /></label><label>Categoria<select value={planDraft.category} onChange={(event) => setPlanDraft((current) => ({ ...current, category: event.target.value as PlanningCategory }))}>{categories.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label>Prioridade<select value={planDraft.priority} onChange={(event) => setPlanDraft((current) => ({ ...current, priority: event.target.value as PlanningPriority }))}>{priorities.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label>Status<select value={planDraft.status} onChange={(event) => setPlanDraft((current) => ({ ...current, status: event.target.value as PlanningStatus }))}>{statuses.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label>Data de início<input type="date" value={planDraft.start_date} onChange={(event) => setPlanDraft((current) => ({ ...current, start_date: event.target.value }))} /></label><label>Prazo final<input type="date" value={planDraft.due_date} onChange={(event) => setPlanDraft((current) => ({ ...current, due_date: event.target.value }))} /></label><label className="planning-form-grid__wide">Descrição<textarea rows={2} value={planDraft.description} onChange={(event) => setPlanDraft((current) => ({ ...current, description: event.target.value }))} /></label><label className="planning-form-grid__wide">Objetivo esperado<textarea rows={2} value={planDraft.expected_outcome} onChange={(event) => setPlanDraft((current) => ({ ...current, expected_outcome: event.target.value }))} /></label>{!editingPlan ? <label className="planning-form-grid__wide">Tarefas iniciais <small>Uma tarefa por linha. {planDraft.task_titles.split('\n').filter((line) => line.trim()).length} tarefa(s)</small><textarea rows={4} value={planDraft.task_titles} onChange={(event) => setPlanDraft((current) => ({ ...current, task_titles: event.target.value }))} placeholder="Ex.: Revisar dados atuais" /></label> : null}<label className="planning-form-grid__wide">Observações<textarea rows={2} value={planDraft.observations} onChange={(event) => setPlanDraft((current) => ({ ...current, observations: event.target.value }))} /></label><label>Cliente relacionado<select value={planDraft.links.find((link) => link.entity_type === 'customer')?.entity_id ?? ''} onChange={(event) => setLink('customer', event.target.value)}><option value="">Nenhum cliente</option>{related.customers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Fornecedor relacionado<select value={planDraft.links.find((link) => link.entity_type === 'supplier')?.entity_id ?? ''} onChange={(event) => setLink('supplier', event.target.value)}><option value="">Nenhum fornecedor</option>{related.suppliers.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="planning-form-grid__wide">Produto relacionado<select value={planDraft.links.find((link) => link.entity_type === 'product')?.entity_id ?? ''} onChange={(event) => setLink('product', event.target.value)}><option value="">Nenhum produto</option>{related.products.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Compra relacionada<select value={planDraft.links.find((link) => link.entity_type === 'purchase')?.entity_id ?? ''} onChange={(event) => setLink('purchase', event.target.value)}><option value="">Nenhuma compra</option>{related.purchases.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Pedido relacionado<select value={planDraft.links.find((link) => link.entity_type === 'order')?.entity_id ?? ''} onChange={(event) => setLink('order', event.target.value)}><option value="">Nenhum pedido</option>{related.orders.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Conta a pagar<select value={planDraft.links.find((link) => link.entity_type === 'payable')?.entity_id ?? ''} onChange={(event) => setLink('payable', event.target.value)}><option value="">Nenhuma conta</option>{related.payables.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Conta a receber<select value={planDraft.links.find((link) => link.entity_type === 'receivable')?.entity_id ?? ''} onChange={(event) => setLink('receivable', event.target.value)}><option value="">Nenhuma conta</option>{related.receivables.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div>{error ? <ErrorState message={error} /> : null}<footer className="admin-modal__actions"><button type="button" className="btn btn--secondary" onClick={() => setPlanFormOpen(false)}>Cancelar</button><button type="submit" className="btn btn--primary" disabled={isSaving}>{isSaving ? 'Salvando…' : editingPlan ? 'Salvar alterações' : 'Criar planejamento'}</button></footer></form></div> : null}

    {taskFormOpen && detailPlan ? <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !isSaving) setTaskFormOpen(false); }}><form className="admin-modal planning-form-modal" role="dialog" aria-modal="true" aria-labelledby="task-form-title" onSubmit={(event) => void saveTask(event)}><header className="admin-modal__header"><div><span className="eyebrow">{detailPlan.title}</span><h2 id="task-form-title">{editingTask ? 'Editar tarefa' : 'Nova tarefa'}</h2></div><button type="button" aria-label="Fechar" onClick={() => setTaskFormOpen(false)}>×</button></header><label>Título<input required minLength={1} value={taskDraft.title} onChange={(event) => setTaskDraft((current) => ({ ...current, title: event.target.value }))} /></label><label>Etapa<input maxLength={80} value={taskDraft.stage} onChange={(event) => setTaskDraft((current) => ({ ...current, stage: event.target.value }))} /></label><label>Descrição<textarea rows={2} value={taskDraft.description} onChange={(event) => setTaskDraft((current) => ({ ...current, description: event.target.value }))} /></label><label>Prioridade<select value={taskDraft.priority} onChange={(event) => setTaskDraft((current) => ({ ...current, priority: event.target.value as PlanningPriority }))}>{priorities.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label>Prazo<input type="date" value={taskDraft.due_date} onChange={(event) => setTaskDraft((current) => ({ ...current, due_date: event.target.value }))} /></label><label>Status<select value={taskDraft.status} onChange={(event) => setTaskDraft((current) => ({ ...current, status: event.target.value as PlanningTaskStatus }))}><option value="pending">Pendente</option><option value="in_progress">Em andamento</option><option value="completed">Concluída</option></select></label><label>Responsável<select value={taskDraft.assignee_id} onChange={(event) => setTaskDraft((current) => ({ ...current, assignee_id: event.target.value }))}><option value="">Sem responsável</option>{related.assignees.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Observações<textarea rows={2} value={taskDraft.observations} onChange={(event) => setTaskDraft((current) => ({ ...current, observations: event.target.value }))} /></label>{error ? <ErrorState message={error} /> : null}<footer className="admin-modal__actions"><button type="button" className="btn btn--secondary" onClick={() => setTaskFormOpen(false)}>Cancelar</button><button type="submit" className="btn btn--primary" disabled={isSaving}>{isSaving ? 'Salvando…' : 'Salvar tarefa'}</button></footer></form></div> : null}

    {goalFormOpen ? <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !isSaving) setGoalFormOpen(false); }}><form className="admin-modal planning-form-modal" role="dialog" aria-modal="true" aria-labelledby="goal-form-title" onSubmit={(event) => void saveGoal(event)}><header className="admin-modal__header"><div><span className="eyebrow">METAS</span><h2 id="goal-form-title">{editingGoal ? 'Editar meta' : 'Nova meta'}</h2></div><button type="button" aria-label="Fechar" onClick={() => setGoalFormOpen(false)}>×</button></header><label>Nome<input required minLength={2} value={goalDraft.name} onChange={(event) => setGoalDraft((current) => ({ ...current, name: event.target.value }))} /></label><label>Categoria<select value={goalDraft.category} onChange={(event) => setGoalDraft((current) => ({ ...current, category: event.target.value as PlanningCategory }))}>{categories.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label>Valor inicial<input type="number" min="0" step="0.01" value={goalDraft.initial_value} onChange={(event) => setGoalDraft((current) => ({ ...current, initial_value: event.target.value }))} /></label><label>Valor-alvo<input required type="number" min="0" step="0.01" value={goalDraft.target_value} onChange={(event) => setGoalDraft((current) => ({ ...current, target_value: event.target.value }))} /></label><label>Valor atual<input required type="number" min="0" step="0.01" value={goalDraft.current_value} onChange={(event) => setGoalDraft((current) => ({ ...current, current_value: event.target.value }))} /></label><label>Unidade<input required maxLength={40} placeholder="clientes, unidades, R$ ou %" value={goalDraft.unit} onChange={(event) => setGoalDraft((current) => ({ ...current, unit: event.target.value }))} /></label><label>Data de início<input type="date" value={goalDraft.start_date} onChange={(event) => setGoalDraft((current) => ({ ...current, start_date: event.target.value }))} /></label><label>Prazo<input type="date" value={goalDraft.due_date} onChange={(event) => setGoalDraft((current) => ({ ...current, due_date: event.target.value }))} /></label><label>Planejamento relacionado<select value={goalDraft.planning_id} onChange={(event) => setGoalDraft((current) => ({ ...current, planning_id: event.target.value }))}><option value="">Nenhum</option>{activePlans.map((plan) => <option key={plan.id} value={plan.id}>{plan.title}</option>)}</select></label><label>Status<select value={goalDraft.status} onChange={(event) => setGoalDraft((current) => ({ ...current, status: event.target.value as PlanningGoal['status'] }))}><option value="in_progress">Em andamento</option><option value="completed">Concluída</option><option value="cancelled">Cancelada</option></select></label><label>Descrição<textarea rows={2} value={goalDraft.description} onChange={(event) => setGoalDraft((current) => ({ ...current, description: event.target.value }))} /></label>{error ? <ErrorState message={error} /> : null}<footer className="admin-modal__actions"><button type="button" className="btn btn--secondary" onClick={() => setGoalFormOpen(false)}>Cancelar</button><button type="submit" className="btn btn--primary" disabled={isSaving}>{isSaving ? 'Salvando…' : 'Salvar meta'}</button></footer></form></div> : null}
  </div></>;
}
